import { observer } from 'mobx-react-lite';
import React, { useEffect, useState } from 'react';
import { useContext } from 'react';
import { Context } from '../index';
import { Button, Card, Col, Container, Form, Row, Spinner } from 'react-bootstrap'
import { getOrder } from '../http/orderAPI';
import { useHistory } from 'react-router-dom/cjs/react-router-dom';
import { ORDER_ROUTE } from '../utils/consts';

const Orders = observer(() => {
  const {order} = useContext(Context)
  const history = useHistory()
  const [loading, setLoading] = useState(true)

  function stop(){
    setLoading(false)
  }

  useEffect(() =>{
    getOrder().then(data => order.setAllOrders(data.oneUser)).finally(setTimeout(stop, 1000))
    console.log(data.oneUser)
  }, [])

  if (loading){
    return <Spinner animation={"grow"}/>
  }

  return (
    <Container className="min-vh-100 d-flex flex-sm-column mt-3">
      {order.allOrders.map(oneOrder =>
        <Container key={oneOrder.id}>
          <h4><b>Замовлення №{oneOrder.id}</b></h4>
          <Button onClick={() => history.push(ORDER_ROUTE +  '/' + oneOrder.id)}>Переглянути</Button>
          <hr/>
        </Container>
      )}
    </Container>
  );
});

export default Orders;
